use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let matrix = input.as_array().unwrap();
    let mut rows = Vec::new();
    for row in matrix {
        let mut sum = 0;
        for num in row.as_array().unwrap() {
            sum += num.as_i64().unwrap();
        }
        rows.push(serde_json::Value::from(sum));
    }
    Value::Array(rows)
}
